--- a/src/ConnectionPool.cs
+++ b/src/ConnectionPool.cs
@@ -45,12 +45,18 @@ public class ConnectionPool
     public async Task<Connection> AcquireAsync(CancellationToken ct)
     {
-        var connection = await _pool.GetAsync();
-        if (connection == null)
+        using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
+        timeoutCts.CancelAfter(_options.AcquireTimeout);
+
+        try
         {
-            throw new TimeoutException("Pool exhausted");
+            var connection = await _pool.GetAsync(timeoutCts.Token);
+            return connection ?? throw new PoolExhaustedException();
+        }
+        catch (OperationCanceledException) when (!ct.IsCancellationRequested)
+        {
+            throw new TimeoutException(
+                $"Failed to acquire connection within {_options.AcquireTimeout.TotalSeconds}s");
         }
-        return connection;
     }
